// Pick related news articles for internal links (province pages, number pages).
// Data comes from news-index.js, generated by scripts/build-news-index.mjs.

import { NEWS } from './news-index.js';

/**
 * Up to `limit` news items: articles tagged with one of `provinceSlugs` first
 * (newest first), then the newest nationwide articles. No duplicates.
 * Each item: { href, title, date, local }.
 */
export function relatedNews(provinceSlugs = [], limit = 4, news = NEWS) {
  const want = new Set(provinceSlugs);
  const local = want.size ? news.filter((n) => n.provinces.some((s) => want.has(s))) : [];
  const picks = [...local.map((n) => ({ ...n, local: true })), ...news.map((n) => ({ ...n, local: false }))];
  const seen = new Set();
  return picks
    .filter((n) => (seen.has(n.slug) ? false : seen.add(n.slug)))
    .slice(0, limit)
    .map((n) => ({ href: `/news/${n.slug}`, title: n.title, date: n.date, local: n.local }));
}

const TH_MONTHS = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];

/** '2026-10-28' -> '28 ต.ค. 2569' (Buddhist year). */
export function thaiShortDate(iso) {
  const m = String(iso || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return '';
  return `${Number(m[3])} ${TH_MONTHS[Number(m[2]) - 1]} ${Number(m[1]) + 543}`;
}
